package com.ashkan.hotel;

import java.sql.*;import java.util.*;
public final class GuestRepository extends JdbcDomainRepository {
 public record Guest(String id,String firstName,String lastName,String email,String phone,String nationality){public Guest{req(id);req(firstName);req(lastName);if(email!=null&&!email.isBlank()&&!email.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$"))throw new IllegalArgumentException("Invalid email");}}
 public record History(long id,String guestId,String eventType,String description,java.time.Instant occurredAt){}
 private final TtlCache<String,Optional<Guest>> cache=new TtlCache<>(CacheSettings.ttlMillis(),CacheSettings.maxEntries());
 private final RedisCacheClient redis=new RedisCacheClient(); private String redisKey(String id){return "hotelsphere:guest:"+id;}
 public GuestRepository(String u,String n,String p,int z){super(u,n,p,z);}
 public void save(Guest g)throws SQLException{withConnection(c->{try(PreparedStatement p=c.prepareStatement("INSERT INTO guest_profiles(guest_id,first_name,last_name,email,phone,nationality) VALUES(?,?,?,?,?,?) ON CONFLICT(guest_id) DO UPDATE SET first_name=EXCLUDED.first_name,last_name=EXCLUDED.last_name,email=EXCLUDED.email,phone=EXCLUDED.phone,nationality=EXCLUDED.nationality,updated_at=NOW(),deleted_at=NULL")){p.setString(1,g.id());p.setString(2,g.firstName());p.setString(3,g.lastName());p.setString(4,g.email());p.setString(5,g.phone());p.setString(6,g.nationality());p.executeUpdate();}return null;});cache.invalidate(g.id());redis.delete(redisKey(g.id()));}
 public Optional<Guest> find(String id)throws SQLException{Optional<Guest> cached=cache.get(id);if(cached!=null)return cached;String remote=redis.get(redisKey(id));if(remote!=null){try{String[] a=CacheCodec.unpack(remote,6);Optional<Guest> value=Optional.of(new Guest(a[0],a[1],a[2],a[3],a[4],a[5]));cache.put(id,value);return value;}catch(RuntimeException ignored){redis.delete(redisKey(id));}}Optional<Guest> result=withConnection(c->{try(PreparedStatement p=c.prepareStatement("SELECT * FROM guest_profiles WHERE guest_id=? AND deleted_at IS NULL")){p.setString(1,id);try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(new Guest(r.getString("guest_id"),r.getString("first_name"),r.getString("last_name"),r.getString("email"),r.getString("phone"),r.getString("nationality"))):Optional.empty();}}});cache.put(id,result);result.ifPresent(g->redis.set(redisKey(id),CacheCodec.pack(g.id(),g.firstName(),g.lastName(),g.email(),g.phone(),g.nationality()),(int)Math.max(1,CacheSettings.ttlMillis()/1000)));return result;}
 public void addHistory(String guestId,String eventType,String description)throws SQLException{withConnection(c->{try(PreparedStatement p=c.prepareStatement("INSERT INTO guest_history(guest_id,event_type,description) VALUES(?,?,?)")){p.setString(1,guestId);p.setString(2,eventType);p.setString(3,description);p.executeUpdate();}return null;});}
 public List<Guest> list(int limit,int offset,String search)throws SQLException{return withConnection(c->{String sql="SELECT * FROM guest_profiles WHERE deleted_at IS NULL"+(search==null||search.isBlank()?"":" AND (lower(first_name) LIKE ? OR lower(last_name) LIKE ? OR lower(email) LIKE ?)")+" ORDER BY last_name,first_name LIMIT ? OFFSET ?";try(PreparedStatement p=c.prepareStatement(sql)){int i=1;if(search!=null&&!search.isBlank()){String q="%"+search.toLowerCase(Locale.ROOT)+"%";p.setString(i++,q);p.setString(i++,q);p.setString(i++,q);}p.setInt(i++,limit);p.setInt(i,offset);try(ResultSet r=p.executeQuery()){List<Guest> out=new ArrayList<>();while(r.next())out.add(new Guest(r.getString("guest_id"),r.getString("first_name"),r.getString("last_name"),r.getString("email"),r.getString("phone"),r.getString("nationality")));return out;}}});}
 public void softDelete(String id)throws SQLException{withConnection(c->{try(PreparedStatement p=c.prepareStatement("UPDATE guest_profiles SET deleted_at=NOW(),updated_at=NOW() WHERE guest_id=? AND deleted_at IS NULL")){p.setString(1,id);p.executeUpdate();}return null;});cache.invalidate(id);redis.delete(redisKey(id));}
 private static void req(String s){if(s==null||s.isBlank())throw new IllegalArgumentException("Required guest field missing");}
}
